  wtt = `Styrekulens friksjon`,
  Ttt = `Styrekulens friksjon bestemmer hvor raskt styrekulen stopper opp når den spinner fritt.`,
  Ett = `Styrekulens friksjon – av`,
  Dtt = `Hvis dette er slått av, har ikke styrekulen noe fremdrift. Det fungerer som om styrekulemodusen er slått av.`,
  Ott = `Styrekulens friksjon – lav`,
  ktt = `Med lav friksjon fortsetter styrekulen å spinne i en lang periode etter at den flikkes, og stopper langsomt opp.`,
  Att = `Styrekulens friksjon – middels`,
  jtt = `Med middels friksjon fortsetter styrekulen å spinne i en periode etter at den flikkes, og stopper gradvis opp.`,
  Mtt = `Styrekulens friksjon – høy`,
  Ntt = `Med høy friksjon fortsetter styrekulen å spinne i en kort periode etter at den flikkes, og stopper raskt opp.`,
  Ptt = `Styrekulens friksjon – ingen`,
  Ftt = `Med ingen friksjon fortsetter styrekulen å spinne evig etter at den flikkes, uten andre inngrep.`,
  Itt = `Vertikal friksjonsskala`,
  Ltt = `Vertikal friksjon bestemmer hvor raskt den vertikale bevegelsen stopper opp i forhold til den horisontale bevegelsen. Midt på glidebryteren stopper den likt, under midten stopper den saktere, mens over stopper den raskere. Det er vanligvis hensiktsmessig å ha høy vertikal friksjon i spill der du kontrollerer kameraet, slik at raske sveip først og fremst brukes til å dreie kameraet langs den horisontale aksen.`,
  Rtt = `Skala for vertikal følsomhet`,
  ztt = `Skalaen for vertikal følsomhet bestemmer hvor mye vertikal bevegelse som skjer i forhold til horisontal bevegelse. Midt på glidebryteren er bevegelsen den samme, under midten er vertikal bevegelse mindre enn horisontal, mens over midten gir mer vertikal bevegelse i forhold til horisontal.`,
  Btt = `Utjevning`,
  Vtt = `Utjevning hjelper med å fjerne støy og skjelving fra musen. Mindre verdier gir mindre filtrering, mens høyere verdier gir mer filtrering og jevnere bevegelse.`,
  Htt = `Akselerasjon`,
